Import ListNotations. Import AX2. Import AX2B. Import AX2S.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

Import PSMC.
Module PSV.
Abbreviation RSEGS := PML.RSEGS.
Abbreviation mem := (word -> option byte).
Abbreviation uv := PB.uv.

(* [comment removed for export] *)
Definition rview (i : nat) (c : CC.cutpoint) (ps : SR.post_spec) (j : nat) (nxj : nat) : option (PB4.pvals2 * PB4.pvals2 * expr * expr * PSM2.delta) :=
  match PSM2.ldelta i c ps, PSM2.vw j with
  | Some (pv, lv, pe, ce, d), Some (pvj, pej, cej) =>
      if (forallb (fun ab : expr * expr => expr_eqb (fst ab) (snd ab)) (combine (PSM2.flds pvj) (PSM2.flds lv)) && expr_eqb pej pe && expr_eqb cej ce
          && forallb (APC.expr_vars_lt nxj) (pe :: ce :: PSM2.flds lv))%bool then Some (pv, lv, pe, ce, d) else None
  | _, _ => None
  end.
Definition same_state (d : PSM2.delta) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$d;R+0!2'1!2'1!2'1!2'1!2'1-2RN$x;R!1+2+3+4!1'5#12$e;R+3,6,7-2RN$x;R!1+2+8+4!1'9#12$z;R+8,6,7-2RN$x;R!1+2+8+4!1':#12$z;R+8,6,7-2RN$x;R!1+2+8+4!1';#12$z;R+8,6,7-2RN$x;R!1+2+8+4!1'<#12$z;R+8,6,7!1'=!1'>#1").
Definition vis_chk2 (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S50!2+L+M+M!2+L0+3!2+L1+3!2+L2+0!1,^6!2+L+3+3$i;R+?$c;R+@$k;R+?$ps;R+A$t;R+B-BRN$t;R+B+4#12$j;R+?$s;R'C,7$pc;R+8-4RN$~R+4+4!2'D!2'E#1'F!2'E#1'G2-2RN$x;R!1+2+?+4!3'H'I#6#42$j;R+?-JRN$x;R+J+4!1'K#79-JRN$x;R+J+4!1'K#19,6,6,6,6,6,6,6,6-2RN$x;R!1+23+4!5'N#7#6#4#1!2'O!1'P!1'Q#1'R2$p;R3-LRN$p;R!2+L2+0+4#11$p0;R2$d;R+0-LRN$p0;R!2+L1+3+4#21$p1;R1$ce;R+3-LRN$p1;R!2+L0+3+4#21$p2;R0$pe;R+3-LRN$p2;R!2+L+M+M+4#21$pv;R+M$lv;R+M!2'1!2'1!2'1!2'1!2'1!2'1!1'S#7!1'=!2'T#@,U!2'V!1'W#:!1'W#@!2'X'Y#:-LRN$x;R!2+L+8+8+4!2'Z!1'[#=!1'\#21$lo;R+8$hi;R+8!2'^0!1,^1|41;#2!2'^2!4'^3'^4#:'^54!4'^3'^4#@'^54-3RN$x;R+3+4!4'^3+3};!1'^7#=!1,^8,^98$z;R+8!2'D!2'E#1,^9!2'E#1!1,^1,^:$n;R+?,6$op;R+^;$a;R+3$b;R+3,6$op;R+^;$a;R+3$b;R+3,6$op;R+^<$a;R+3$b;R+3,6$op;R+^<$a;R+3$b;R+3,6$sx;R+4$lo;R+?$n;R+?$e;R+3,6$sx;R+4$k0;R+?$i0;R+8$n;R+?,6,6,6,6,6,6,6,6,6,6,6,7").
Lemma vis2_ok : CH2.leaves_all G.CPS G.TAGS vis_chk2 = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,^=+4,7!3+^>+4!3'^?'^@'^A'^B,7").
Qed.

