(* [comment removed for export] *)
Definition WVIS (g g' : PMES.eghost) : Prop :=
  exists ev pay, match ev with PMES.EvNull | PMES.EvBool _ => True | _ => False end /\
    PMES.g_es g' = PMES.estep (PMES.g_es g) ev /\ PMES.pay_ok ev pay /\ PMES.g_len g' = PMES.g_len g + PMES.ev_ind (PMES.g_es g) ev + pay.
(* [comment removed for export] *)
Definition OBLT_VIS_RET : Prop := forall i c k ps1 pc j cj pv lv pe ce d E1 E' R' (M1 M' : mem) E2 (M2 : mem) g',
  is_leaf i c k ps1 (CC.TOther pc) -> (pc = 247028 \/ pc = 247212) -> SR.ps_pc ps1 = pc -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj ->
  PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> kind_of i = KInv -> kind_of j = KVis ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> env_agree (CC.cp_nx cj - APC.NCS) E' E2 ->
  XI i E1 M1 -> PSI.SIM I eg i E1 M1 -> WVIS eg g' ->
  (forall a, (PB2.ls_foot a \/ uv E1 (PB4.pv_sb pv) <= a < uv E1 (PB4.pv_scend pv)) -> M2 (Z_to_bv 64 a) = M' (Z_to_bv 64 a)) ->
  (forall a, uv E1 (PB4.pv_sb pv) <= a < uv E1 (PB4.pv_scend pv) -> M2 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  PSI.XI I g' j E2 M2 -> PSI.SIM I g' j E2 M2.
Hypothesis OBL_VIS_RET : OBLT_VIS_RET.

